        char const* arg_name_c = nullptr;
        if (argpol != tr_option::Arg::None)
        {
            arg_name_c = s.arg_name.c_str();
        }

        tr_option opt{};
        opt.val = val;
        opt.longName = s.long_name.c_str();
        opt.description = s.desc.c_str();
        opt.shortName = short_name_c;
        opt.arg = argpol;
        opt.argName = arg_name_c;
        opts.push_back(opt);
        opt_strs.push_back(std::move(s));
    }

    // Sentinel terminator: zeroed/empty entry; library convention typically treats null longName/shortName as end
    opts.push_back(tr_option{});

    // 3) Build argv array
    // argc in [0..8]
    int argc = static_cast<int>(*FUZZ_PARAM(unsigned int) % 9U);

    std::vector<std::string> arg_storage;
    std::vector<char const*> argv;
    arg_storage.reserve(std::max(1, argc));
    argv.reserve(std::max(1, argc));

    // Ensure argv[0] exists and is a program name if argc>0
    if (argc > 0)
    {
        arg_storage.emplace_back(FUZZ_PARAM_STR());
        argv.push_back(arg_storage.back().c_str());
    }

    // Populate remaining argv entries with a mix of options and values
    for (int i = 1; i < argc; ++i)
    {
        // Choose an option from our table
        tr_option const* opt = &opts[static_cast<size_t>(*FUZZ_PARAM(unsigned int) % n_opts)];
        bool use_long = (*FUZZ_PARAM(unsigned int) & 1U) != 0U && opt->longName != nullptr && *opt->longName != '\0';
