                    arg_storage.emplace_back(std::move(tok));
                    argv.push_back(arg_storage.back().c_str());
                    if (i + 1 < argc)
                    {
                        arg_storage.emplace_back(std::move(val));
                        argv.push_back(arg_storage.back().c_str());
                        ++i; // consumed next slot for value
                    }
                    else
                    {
                        // no room for value; leave as just the option (may provoke TR_OPT_ERR)
                    }
                    continue;
                }
            }
            arg_storage.emplace_back(std::move(tok));
            argv.push_back(arg_storage.back().c_str());
        }
        else
        {
            // short option form: -x [value]
            char short_ch = opt->shortName != nullptr && *opt->shortName != '\0' ? opt->shortName[0] : 'x';
            std::string tok;
            tok.push_back('-');
            tok.push_back(short_ch);
            if (opt->arg != tr_option::Arg::None)
            {
                std::string val = FUZZ_PARAM_STR();
                if (attach_value)
