                    tok += val;
                }
                else
                {
                    arg_storage.emplace_back(std::move(tok));
                    argv.push_back(arg_storage.back().c_str());
                    if (i + 1 < argc)
                    {
                        arg_storage.emplace_back(std::move(val));
                        argv.push_back(arg_storage.back().c_str());
                        ++i;
                    }
                    else
                    {
                        // no room for value; may cause TR_OPT_ERR
                    }
                    continue;
                }
            }
            arg_storage.emplace_back(std::move(tok));
            argv.push_back(arg_storage.back().c_str());
        }
    }

    // Ensure argv pointer array size matches argc if argc>0
    if (argc > 0 && static_cast<int>(argv.size()) != argc)
    {
        // Adjust argc to the actual argv size to preserve the invariant
        argc = static_cast<int>(argv.size());
    }

    // 4) Invoke tr_getopt in a loop until done; enforce documented behaviors
    char const* setme = nullptr;
    for (;;)
    {
        int ret = tr_getopt(usage.c_str(), argc, argv.empty() ? nullptr : argv.data(), opts.data(), &setme);
        if (ret == 0) // TR_OPT_DONE
