            break;
        }
        if (ret == -1 || ret == -2) // TR_OPT_ERR or TR_OPT_UNK
        {
            // Bail on syntax/argument errors or unknown options per guidance
            FUZZ_BAIL();
        }

        // Find matching option metadata by val to validate setme when needed
        tr_option const* found = nullptr;
        for (size_t i = 0; i < opts.size(); ++i)
        {
            if (opts[i].longName == nullptr && opts[i].shortName == nullptr)
