import os
import random
import string
from typing import List

# Data type: filesystem path
# We need to provide interesting, but valid, initial buffers that will be used to seed
# FUZZ_PARAM_STR and FUZZ_PARAM_FILENAME in the provided stubs. The stubs expect:
# - app names, directory paths, filenames with extensions, temporary templates, etc.
# - Paths should often exist when used via FUZZ_PARAM_FILENAME (the harness promises existence),
#   but our buffer seeds should suggest realistic path-like strings with a variety of shapes.
# Strategy:
# - Generate a small corpus of plausible path strings (absolute/relative, with separators, dots, spaces,
#   unicode, extensions, multiple dirs, trailing slash or not).
# - Prefer including typical filenames used by Transmission code paths: .torrent, .json, .benc, cookies,
#   and temporary templates that end with XXXXXX.
# - Keep result under 4096 bytes.
# - The harness will split buffers to feed multiple FUZZ_PARAM_STR/FILENAME calls; hence we output
#   a newline-delimited list of candidate strings so the fuzzer runtime can pick segments.

SEP_POSIX = "/"
SEP_WIN = "\\\\"

EXTS = [
    ".torrent", ".json", ".benc", ".txt", ".bin", ".html", ".jpg", ".mkv", ".log"
]

DIR_NAMES = [
    "config", "Transmission", "downloads", "incomplete", "tmp", "cache", "data", "watch",
    "Resume", "Blocklist"
]

FILE_BASENAMES = [
    "settings", "session", "blocklist", "cookies", "metainfo", "resume", "torrent",
    "tracker", "stats", "piece-map", "rpc"
]

UNICODE_PARTS = [
    "naïve", "文件", "данные", "Δοκιμή", "スペース", "données", "espaço"
]

SAFE_CHARS = string.ascii_letters + string.digits + "-_ ."


def rand_name(rng: random.Random, base_list: List[str]) -> str:
    if rng.random() < 0.5:
        return rng.choice(base_list)
    # synthesize
    core = "".join(rng.choice(SAFE_CHARS) for _ in range(rng.randint(3, 12))).strip()
    return core or rng.choice(base_list)


def rand_ext(rng: random.Random) -> str:
    if rng.random() < 0.85:
        return rng.choice(EXTS)
    # rare custom extension
    return "." + "".join(rng.choice(string.ascii_lowercase) for _ in range(rng.randint(2, 5)))


def join_paths(parts: List[str], sep: str) -> str:
    # Avoid empty components creating duplicate separators
    parts = [p for p in parts if p is not None and p != ""]
    path = sep.join(parts)
    # Normalize accidental dup seps
    while sep * 2 in path:
        path = path.replace(sep * 2, sep)
    return path


def make_abs_posix(rng: random.Random) -> str:
    depth = rng.randint(1, 4)
    comps = [rand_name(rng, DIR_NAMES) for _ in range(depth)]
    leaf = rand_name(rng, FILE_BASENAMES)
    if rng.random() < 0.8:
        leaf += rand_ext(rng)
    return SEP_POSIX + join_paths(comps + [leaf], SEP_POSIX)


def make_abs_win(rng: random.Random) -> str:
    drive = rng.choice(["C:", "D:", "E:"])
    depth = rng.randint(1, 3)
    comps = [rand_name(rng, DIR_NAMES) for _ in range(depth)]
    leaf = rand_name(rng, FILE_BASENAMES)
    if rng.random() < 0.8:
        leaf += rand_ext(rng)
    return drive + SEP_WIN + join_paths(comps + [leaf], SEP_WIN)


def make_rel(rng: random.Random) -> str:
    depth = rng.randint(0, 3)
    prefix = []
    if rng.random() < 0.4:
        prefix.append(".")
    if rng.random() < 0.2:
        prefix.append("..")
    comps = [rand_name(rng, DIR_NAMES) for _ in range(depth)]
    if rng.random() < 0.5:
        # directory path (no leaf file)
        path = join_paths(prefix + comps, SEP_POSIX)
        if not path:
            path = "."
        return path
    leaf = rand_name(rng, FILE_BASENAMES)
    if rng.random() < 0.85:
        leaf += rand_ext(rng)
    return join_paths(prefix + comps + [leaf], SEP_POSIX)


def make_tmp_template(rng: random.Random) -> str:
    # Template ending with at least six X for mkstemp/mkdtemp style
    base = rand_name(rng, ["trfuzz", "temp", "tmpfile", "trtmp"]) + "-"
    suffix = "X" * rng.randint(6, 8)
    parent = rng.choice([
        "/tmp", "/var/tmp", join_paths([".", "tmp"], SEP_POSIX)
    ])
    return join_paths([parent, base + suffix], SEP_POSIX)


def make_cookie_path(rng: random.Random) -> str:
    base = rand_name(rng, ["cookies", "cookiejar", "cookie-store"]) + ".txt"
    dirpath = SEP_POSIX + join_paths(["home", rand_name(rng, ["user", "tester", "transmission"]) , ".cache"], SEP_POSIX)
    return join_paths([dirpath, base], SEP_POSIX)


def make_with_unicode(rng: random.Random) -> str:
    depth = rng.randint(1, 3)
    comps = []
    for _ in range(depth):
        if rng.random() < 0.5:
            comps.append(rng.choice(UNICODE_PARTS))
        else:
            comps.append(rand_name(rng, DIR_NAMES))
    leaf = rng.choice(UNICODE_PARTS) + rand_ext(rng)
    return SEP_POSIX + join_paths(comps + [leaf], SEP_POSIX)


def make_dir_like(rng: random.Random) -> str:
    # Directory path optionally with trailing slash
    depth = rng.randint(1, 4)
    comps = [rand_name(rng, DIR_NAMES) for _ in range(depth)]
    path = SEP_POSIX + join_paths(comps, SEP_POSIX)
    if rng.random() < 0.5:
        path += "/"
    return path


def make_filename_only(rng: random.Random) -> str:
    leaf = rand_name(rng, FILE_BASENAMES) + rand_ext(rng)
    return leaf


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    builders = [
        make_abs_posix,
        make_abs_win,
        make_rel,
        make_tmp_template,
        make_cookie_path,
        make_with_unicode,
        make_dir_like,
        make_filename_only,
    ]

    entries: List[str] = []

    # Ensure a diverse fixed core set
    for b in builders:
        try:
            entries.append(b(rng))
        except Exception:
            continue

    # Add a few more randomized mixes to expand coverage
    for _ in range(rng.randint(6, 12)):
        b = rng.choice(builders)
        try:
            entries.append(b(rng))
        except Exception:
            pass

    # Append some filenames with specific interesting extensions and patterns
    for ext in EXTS:
        name = rand_name(rng, FILE_BASENAMES) + ext
        # Sometimes place in a common directory
        if rng.random() < 0.6:
            base_dir = rng.choice(["/tmp", "/var/tmp", ".", "./downloads", "./incomplete"])\
                .replace("\\", "/")
            entries.append(join_paths([base_dir, name], SEP_POSIX))
        else:
            entries.append(name)

    # Include a couple of long-ish paths (but keep total under 4096)
    for _ in range(2):
        comps = [rand_name(rng, DIR_NAMES) for _ in range(rng.randint(5, 10))]
        leaf = rand_name(rng, FILE_BASENAMES) + rand_ext(rng)
        entries.append(SEP_POSIX + join_paths(comps + [leaf], SEP_POSIX))

    # Deduplicate while preserving order
    seen = set()
    uniq: List[str] = []
    for s in entries:
        if s not in seen and s:
            seen.add(s)
            uniq.append(s)

    # Assemble as newline-delimited to allow the harness to consume multiple values
    blob = ("\n".join(uniq)).encode("utf-8", errors="ignore")

    # Enforce size cap: trim safely on code point boundary by slicing bytes; ensure final newline
    max_len = 4096
    if len(blob) > max_len:
        blob = blob[:max_len]
        # Trim to last newline to avoid cutting a path mid-line
        nl = blob.rfind(b"\n")
        if nl != -1:
            blob = blob[:nl]
    if not blob.endswith(b"\n"):
        blob += b"\n"

    return blob

import random
from typing import List

def _choice(rng: random.Random, seq):
    return seq[rng.randrange(len(seq))]

HOSTS = [
    "localhost",
    "127.0.0.1",
    "::1",
    "example.com",
    "sub.example.com",
    "intranet",
    "10.0.0.1",
    "192.168.1.100",
    "[2001:db8::1]",
]

TLDS = ["com", "net", "org", "io", "local", "lan"]

def _rand_label(rng: random.Random) -> str:
    alpha = "abcdefghijklmnopqrstuvwxyz0123456789"
    n = rng.randint(1, 10)
    return "".join(rng.choice(alpha) for _ in range(n))

def _rand_hostname(rng: random.Random) -> str:
    # Sometimes choose from known hosts
    if rng.random() < 0.4:
        return _choice(rng, HOSTS)
    # Build random domain
    parts = [_rand_label(rng) for _ in range(rng.randint(1, 3))]
    parts.append(_choice(rng, TLDS))
    return ".".join(parts)

def _rand_ipv4(rng: random.Random) -> str:
    return ".".join(str(rng.randint(0, 255)) for _ in range(4))

def _rand_ipv6(rng: random.Random) -> str:
    # Simple full or compressed forms
    if rng.random() < 0.5:
        return ":".join(f"{rng.randrange(0, 65536):x}" for _ in range(8))
    # compressed with brackets optional
    hextets = [f"{rng.randrange(0, 65536):x}" for _ in range(rng.randint(2, 6))]
    return "::".join([":".join(hextets[:len(hextets)//2]), ":".join(hextets[len(hextets)//2:])]).strip(":")

def _wildcardize_host(rng: random.Random, host: str) -> str:
    # Insert wildcards *, ? in plausible places
    s = host
    # With some probability, prefix wildcard subdomain
    if rng.random() < 0.5 and "." in s and not s.startswith("*"):
        s = "*." + s.split(".", 1)[1]
    # Replace some chars with ?
    s_list = list(s)
    for i, ch in enumerate(s_list):
        if ch.isalnum() and rng.random() < 0.1:
            s_list[i] = "?"
    s = "".join(s_list)
    # Suffix wildcard tail occasionally
    if rng.random() < 0.3 and not s.endswith("*"):
        s += "*"
    return s

def _maybe_port(rng: random.Random) -> str:
    # Occasionally add :port, common for RPC whitelists
    if rng.random() < 0.3:
        return f":{rng.randint(1, 65535)}"
    return ""

def _make_pattern(rng: random.Random) -> str:
    kind = rng.random()
    if kind < 0.33:
        base = _rand_hostname(rng)
    elif kind < 0.66:
        base = _rand_ipv4(rng)
    else:
        base = _rand_ipv6(rng)
        # sometimes bracket IPv6
        if rng.random() < 0.5 and not (base.startswith("[") and base.endswith("]")):
            base = f"[{base}]"
    pat = _wildcardize_host(rng, base)
    pat += _maybe_port(rng)
    return pat

def _join_patterns(rng: random.Random, patterns: List[str]) -> str:
    # Use commas, spaces, or mixed separators
    sep_choice = rng.random()
    if sep_choice < 0.34:
        sep = ","
    elif sep_choice < 0.67:
        sep = " "
    else:
        # mix commas and spaces
        parts = []
        for i, p in enumerate(patterns):
            parts.append(p)
            if i != len(patterns) - 1:
                parts.append(", " if rng.random() < 0.5 else " ")
        return "".join(parts)
    # Optionally add extra whitespace variations
    if sep == " ":
        return sep.join(pat for pat in patterns)
    else:
        return sep.join(pat for pat in patterns)

def _ensure_nonempty(s: str) -> str:
    return s if s.strip() else "localhost,127.0.0.1"

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    n = rng.randint(1, 12)
    patterns = []
    # Include some canonical interesting entries to trigger different paths
    canned = [
        "127.0.0.1",
        "localhost",
        "*.local",
        "192.168.*",
        "10.0.0.?",
        "[::1]",
    ]
    # Randomly pick some of the canned ones
    rng.shuffle(canned)
    for c in canned[:rng.randint(1, min(3, len(canned)))]:
        patterns.append(c)
    # Add random patterns
    while len(patterns) < n:
        patterns.append(_make_pattern(rng))
    rng.shuffle(patterns)
    s = _join_patterns(rng, patterns)
    s = _ensure_nonempty(s)
    # Limit to 4096 bytes
    s = s[:4096]
    return s.encode("utf-8")

import random
import string
from typing import List

# Generate valid newline-separated tracker URLs (HTTP/HTTPS). The library accepts any non-null C string,
# but parsers will look for http/https URLs, tiers (blank lines), duplicates, IPv6 literals, ports,
# query/fragment parts, and various paths. We keep inputs valid to exercise parsing paths.

_SCHEMES = ["http", "https"]
_HOST_LABEL_CHARS = string.ascii_lowercase + string.digits
_TLDS = [
    "com", "net", "org", "io", "dev", "local", "example",
]

def _rand_choice(rng: random.Random, seq):
    return seq[rng.randrange(0, len(seq))]

def _rand_label(rng: random.Random, min_len=1, max_len=12) -> str:
    n = rng.randint(min_len, max_len)
    # start with alpha to be DNS-valid
    first = rng.choice(string.ascii_lowercase)
    rest = "".join(rng.choice(_HOST_LABEL_CHARS) for _ in range(max(0, n - 1)))
    return first + rest

def _rand_hostname(rng: random.Random) -> str:
    # Mix regular hostnames and IPv6 literals to hit different code paths
    mode = rng.random()
    if mode < 0.15:
        # IPv6 literal
        hextets = []
        n = rng.randint(2, 8)
        for _ in range(n):
            hextets.append("%x" % rng.randrange(0, 0x10000))
        # sometimes compress with ::
        if rng.random() < 0.5 and len(hextets) > 2:
            cut = rng.randrange(1, len(hextets) - 1)
            hextets = hextets[:cut] + [""] + hextets[cut:]
            if rng.random() < 0.5:
                hextets.insert(cut, "")
        return f"[{'::'.join([h for h in hextets if h != ''] ) if '' in hextets else ':'.join(hextets)}]"
    else:
        labels = [_rand_label(rng) for _ in range(rng.randint(1, 3))]
        tld = _rand_choice(rng, _TLDS)
        return ".".join(labels + [tld])

def _rand_port(rng: random.Random) -> str:
    # Include default and uncommon ports
    candidates = [80, 443, 6969, 8080, 8443, rng.randint(1, 65535)]
    return str(_rand_choice(rng, candidates))

def _rand_path(rng: random.Random) -> str:
    # Prefer announce endpoints, sometimes with subpaths
    parts: List[str] = []
    if rng.random() < 0.6:
        # add some subdirs
        for _ in range(rng.randint(0, 3)):
            part = _rand_label(rng, 2, 10)
            parts.append(part)
        parts.append("announce")
    else:
        parts.append(_rand_label(rng, 3, 10))
    return "/" + "/".join(parts)

def _rand_query(rng: random.Random) -> str:
    if rng.random() < 0.5:
        return ""
    # include typical tracker params sometimes, or arbitrary pairs
    params = []
    if rng.random() < 0.6:
        # typical keys
        keys = ["info_hash", "peer_id", "port", "uploaded", "downloaded", "left"]
        rng.shuffle(keys)
        kcount = rng.randint(1, min(4, len(keys)))
        for k in keys[:kcount]:
            vlen = rng.randint(3, 8)
            v = ''.join(rng.choice(string.ascii_letters + string.digits + "-_" ) for _ in range(vlen))
            params.append(f"{k}={v}")
    else:
        for _ in range(rng.randint(1, 3)):
            k = _rand_label(rng, 2, 8)
            v = _rand_label(rng, 1, 6)
            params.append(f"{k}={v}")
    return "?" + "&".join(params)

def _rand_fragment(rng: random.Random) -> str:
    if rng.random() < 0.2:
        frag = _rand_label(rng, 2, 10)
        return "#" + frag
    return ""

def _make_url(rng: random.Random) -> str:
    scheme = _rand_choice(rng, _SCHEMES)
    host = _rand_hostname(rng)
    # Optional port
    port = ":" + _rand_port(rng) if rng.random() < 0.7 else ""
    path = _rand_path(rng)
    query = _rand_query(rng)
    frag = _rand_fragment(rng)
    return f"{scheme}://{host}{port}{path}{query}{frag}"

def _build_list(rng: random.Random) -> str:
    lines: List[str] = []
    n_primary = rng.randint(1, 6)

    # Optionally include a tier separator (blank line) to exercise grouping
    include_tiers = rng.random() < 0.5

    # Build first tier
    for _ in range(n_primary):
        lines.append(_make_url(rng))

    if include_tiers:
        lines.append("")  # blank line separates tiers
        # Second tier with a few entries, possibly duplicates to test de-dup
        n_second = rng.randint(1, 4)
        for i in range(n_second):
            if i == 0 and rng.random() < 0.5:
                # duplicate one from first tier
                lines.append(rng.choice([u for u in lines if u]))
            else:
                lines.append(_make_url(rng))

    # Sometimes add trailing newline-only line to test parser handling
    if rng.random() < 0.3:
        lines.append("")

    # Ensure not empty and total size within limit
    text = "\n".join(lines)
    if not text:
        text = _make_url(rng)
    if len(text) > 4096:
        text = text[:4096]
    return text


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    text = _build_list(rng)
    # Ensure non-empty and newline-terminated sometimes to hit code path that appends one
    if rng.random() < 0.5 and not text.endswith("\n"):
        text += "\n"
    return text.encode("utf-8")

import random
from typing import List

# Data type: blocklist rules (ASCII file)
# We generate valid, interesting IP/CIDR/range lines, comments, and whitespace.
# Formats covered:
# - Single IPv4 address
# - IPv4 CIDR (a.b.c.d/n)
# - IPv4 range (a.b.c.d - e.f.g.h) with/without spaces
# - Hostname or invalid tokens preceded by comment markers (ignored by parsers that support comments)
# - IPv6 address and IPv6 CIDR (for parsers that accept IPv6)
# - Mixed comments (#, //) and blank lines
# - Large and small CIDR masks, edge ranges, private and public nets
# Keep under 4096 bytes.

def _ipv4(rand: random.Random) -> str:
    return ".".join(str(rand.randint(0, 255)) for _ in range(4))

def _ipv4_public(rand: random.Random) -> str:
    # Avoid reserved/private sometimes, but allow occasionally
    choices = [
        (1, (1, 223)),  # general unicast excluding 0, 224+
    ]
    a = rand.randint(*choices[0][1])
    b = rand.randint(0, 255)
    c = rand.randint(0, 255)
    d = rand.randint(1, 254)
    return f"{a}.{b}.{c}.{d}"

def _ipv6_hextet(rand: random.Random) -> str:
    return f"{rand.randrange(0, 1<<16):x}"

def _ipv6(rand: random.Random) -> str:
    # Simple full form
    return ":".join(_ipv6_hextet(rand) for _ in range(8))

def _cidr_v4(rand: random.Random) -> str:
    ip = _ipv4(rand)
    mask = rand.choice([8, 12, 16, 20, 24, 25, 27, 30])
    return f"{ip}/{mask}"

def _cidr_v6(rand: random.Random) -> str:
    ip = _ipv6(rand)
    mask = rand.choice([32, 48, 56, 64, 96, 112, 128])
    return f"{ip}/{mask}"

def _range_v4(rand: random.Random) -> str:
    # Ensure start <= end numerically
    def ip_to_int(parts: List[int]) -> int:
        v = 0
        for p in parts:
            v = (v << 8) | p
        return v
    def int_to_ip(v: int) -> str:
        return ".".join(str((v >> shift) & 0xff) for shift in (24, 16, 8, 0))

    a = [rand.randint(0, 255) for _ in range(4)]
    b = [rand.randint(0, 255) for _ in range(4)]
    ia, ib = ip_to_int(a), ip_to_int(b)
    if ia > ib:
        ia, ib = ib, ia
    # limit span to something reasonable
    if ib - ia > 65535:
        ib = ia + rand.randint(1, 65535)
    sep = rand.choice([" - ", "-", " -"])  # spacing variants
    return f"{int_to_ip(ia)}{sep}{int_to_ip(ib)}"

def _line_comment(rand: random.Random) -> str:
    marker = rand.choice(["#", "//", ";"])  # some blocklist parsers accept # or ;
    txt = rand.choice([
        " Generated by seed",
        " Blocked trackers",
        " Example entries",
        " IPv6 entries",
        " Ranges and CIDR",
    ])
    return f"{marker}{txt}"

def _single_ipv4(rand: random.Random) -> str:
    # Sometimes private/reserved to exercise acceptance/rejection paths
    if rand.random() < 0.5:
        return _ipv4_public(rand)
    return _ipv4(rand)

def _entry(rand: random.Random) -> str:
    kind = rand.choices(
        population=["cidr4", "range4", "single4", "cidr6", "single6"],
        weights=[35, 25, 20, 10, 10],
        k=1,
    )[0]
    if kind == "cidr4":
        return _cidr_v4(rand)
    if kind == "range4":
        return _range_v4(rand)
    if kind == "single4":
        return _single_ipv4(rand)
    if kind == "cidr6":
        return _cidr_v6(rand)
    # single6
    return _ipv6(rand)

def _decorate(rand: random.Random, line: str) -> str:
    # Add optional inline comment or whitespace
    leading_ws = rand.choice(["", " ", "\t"]) if rand.random() < 0.3 else ""
    trailing_ws = rand.choice(["", " ", "\t"]) if rand.random() < 0.3 else ""
    if rand.random() < 0.25:
        c = rand.choice([" # note", " // note", " ; note"]) if rand.random() < 0.8 else ""
        return f"{leading_ws}{line}{trailing_ws}{c}"
    return f"{leading_ws}{line}{trailing_ws}"

def _header(rand: random.Random, seed: int) -> List[str]:
    hdr = []
    hdr.append(_line_comment(rand))
    hdr.append(f"# seed={seed}")
    # Optionally include a title and format hint
    if rand.random() < 0.6:
        hdr.append("# Format: one rule per line; supports IPv4/IPv6 single, CIDR, or ranges")
    return hdr

def generate(seed: int) -> bytes:
    rand = random.Random(seed)

    lines: List[str] = []
    lines.extend(_header(rand, seed))

    # Insert some blank lines to exercise parser skipping
    if rand.random() < 0.7:
        lines.append("")

    # Produce a mix of entries
    n_blocks = rand.randint(30, 120)

    # Clustered groups: public nets, small masks, and edge cases
    # Group 1: a few broad CIDRs
    for _ in range(rand.randint(3, 8)):
        lines.append(_decorate(rand, _cidr_v4(rand)))

    # Group 2: ranges with various spacings
    lines.append(_line_comment(rand))
    for _ in range(rand.randint(5, 15)):
        lines.append(_decorate(rand, _range_v4(rand)))

    # Group 3: single IPs
    lines.append(_line_comment(rand))
    for _ in range(rand.randint(5, 20)):
        lines.append(_decorate(rand, _single_ipv4(rand)))

    # Group 4: IPv6 entries
    if rand.random() < 0.8:
        lines.append(_line_comment(rand))
        for _ in range(rand.randint(3, 10)):
            if rand.random() < 0.6:
                lines.append(_decorate(rand, _cidr_v6(rand)))
            else:
                lines.append(_decorate(rand, _ipv6(rand)))

    # Top up to n_blocks with a random mix
    while len([l for l in lines if l and not l.strip().startswith(("#", ";", "//"))]) < n_blocks:
        if rand.random() < 0.15:
            lines.append("")
        elif rand.random() < 0.15:
            lines.append(_line_comment(rand))
        else:
            lines.append(_decorate(rand, _entry(rand)))

    # Ensure size limit
    out = "\n".join(lines)
    b = out.encode("utf-8", errors="strict")
    if len(b) > 4096:
        # Trim safely at line boundaries
        trimmed_lines: List[bytes] = []
        total = 0
        for ln in lines:
            lb = (ln + "\n").encode("utf-8")
            if total + len(lb) > 4096:
                break
            trimmed_lines.append(lb)
            total += len(lb)
        b = b"".join(trimmed_lines)
    return b

import random
import string
from typing import List, Tuple

# Target data type: URL
# Fuzzer stubs consume FUZZ_PARAM_STR as URL-like inputs and sometimes embed
# them into larger, well-formed URLs. We generate valid and interesting URLs
# that exercise:
# - Different schemes (http, https, udp, ws, wss)
# - Optional userinfo
# - IPv4, IPv6 literals (with brackets), hostnames, punycode-like labels
# - Explicit ports (common, edge, and out-of-range-looking but still numeric)
# - Paths (including reserved chars, matrix params, dot-segments)
# - Query strings (multiple k=v pairs, duplicates, empty values, percent-enc)
# - Fragments
# - Tracker-like endpoints used by Transmission (announce, scrape)
# - Variants for tracker validation (http/https with announce path)
# - Reasonable length limits (< 4096 bytes)

SAFE_UNRESERVED = string.ascii_letters + string.digits + "-._~"
SUBDELIMS = "!$&'()*+,;="
PCHAR_EXTRA = ":@"  # allowed within path segments
QUERY_EXTRA = "/?"  # query can include these


def _pct_encode(s: str, rng: random.Random) -> str:
    # Percent-encode some characters occasionally to vary code paths
    out = []
    for ch in s:
        if ch not in SAFE_UNRESERVED and rng.random() < 0.5:
            out.append('%{:02X}'.format(ord(ch) & 0xFF))
        else:
            out.append(ch)
    return ''.join(out)


def _rand_label(rng: random.Random, min_len=1, max_len=10) -> str:
    # DNS label-ish: start/end alnum, allow hyphens inside
    length = rng.randint(min_len, max_len)
    if length == 1:
        return rng.choice(string.ascii_lowercase + string.digits)
    mid_len = max(0, length - 2)
    start = rng.choice(string.ascii_lowercase + string.digits)
    mid = ''.join(rng.choice(string.ascii_lowercase + string.digits + '-') for _ in range(mid_len))
    end = rng.choice(string.ascii_lowercase + string.digits)
    return start + mid + end


def _rand_hostname(rng: random.Random) -> str:
    # Mix of normal labels and punycode-like xn-- labels
    nlabels = rng.randint(1, 4)
    labels = []
    for i in range(nlabels):
        if rng.random() < 0.25:
            base = _rand_label(rng, 3, 8)
            # fabricate something that looks like punycode prefix
            labels.append('xn--' + base)
        else:
            labels.append(_rand_label(rng, 1, 12))
    return '.'.join(labels)


def _rand_ipv4(rng: random.Random) -> str:
    return '.'.join(str(rng.randint(0, 255)) for _ in range(4))


def _rand_ipv6(rng: random.Random) -> str:
    # Produce a few common IPv6 forms, including :: shorthand
    def h():
        return '{:x}'.format(rng.randint(0, 0xFFFF))
    if rng.random() < 0.5:
        # full 8 groups
        parts = [h() for _ in range(8)]
        return ':'.join(parts)
    else:
        # compressed: a::b:c, ::1, 2001:db8::
        left = [h() for _ in range(rng.randint(0, 4))]
        right = [h() for _ in range(rng.randint(0, 4))]
        if not left and not right:
            right = [h()]
        return (':'.join(left) if left else '') + '::' + (':'.join(right) if right else '')


def _rand_userinfo(rng: random.Random) -> str:
    if rng.random() < 0.5:
        return ''
    ulen = rng.randint(1, 8)
    plen = rng.randint(0, 8)
    user = ''.join(rng.choice(SAFE_UNRESERVED + SUBDELIMS) for _ in range(ulen))
    if plen == 0:
        return user + '@'
    pwd = ''.join(rng.choice(SAFE_UNRESERVED + SUBDELIMS) for _ in range(plen))
    return f"{user}:{pwd}@"


def _rand_port(rng: random.Random, for_tracker: bool) -> str:
    # trackers commonly use 80/443/6969/8080; include some others
    common = [80, 443, 6969, 8080, 6881, 51413]
    if rng.random() < 0.7:
        port = rng.choice(common)
    else:
        port = rng.randint(1, 65535)
    return f":{port}"


def _rand_path_segments(rng: random.Random, min_seg=0, max_seg=6) -> List[str]:
    nseg = rng.randint(min_seg, max_seg)
    segments = []
    for i in range(nseg):
        if rng.random() < 0.2:
            # dot segment
            seg = '.' if rng.random() < 0.5 else '..'
        else:
            seg_len = rng.randint(0, 12)
            charset = SAFE_UNRESERVED + SUBDELIMS + PCHAR_EXTRA
            seg = ''.join(rng.choice(charset) for _ in range(seg_len))
            # Occasionally add matrix params ;k=v
            if seg and rng.random() < 0.2:
                k = ''.join(rng.choice(string.ascii_lowercase) for _ in range(rng.randint(1, 4)))
                v = ''.join(rng.choice(charset) for _ in range(rng.randint(0, 6)))
                seg += ';' + k + '=' + v
        segments.append(seg)
    return segments


def _rand_query_pairs(rng: random.Random, max_pairs=6) -> List[Tuple[str, str]]:
    npairs = rng.randint(0, max_pairs)
    pairs = []
    for i in range(npairs):
        key_len = rng.randint(0, 10)
        val_len = rng.randint(0, 16)
        charset = SAFE_UNRESERVED + SUBDELIMS
        key = ''.join(rng.choice(charset) for _ in range(key_len))
        val = ''.join(rng.choice(charset + QUERY_EXTRA) for _ in range(val_len))
        # Introduce duplicates or empty values sometimes
        if rng.random() < 0.2:
            key = 'info_hash'  # tracker-relevant
            val = ''.join(rng.choice(string.hexdigits.lower()) for _ in range(40))
        elif rng.random() < 0.2:
            key = 'peer_id'
            val = '-TR' + ''.join(rng.choice(string.digits) for _ in range(4)) + '-abcdefghij'
        pairs.append((key, val))
    return pairs


def _build_query(pairs: List[Tuple[str, str]], rng: random.Random) -> str:
    if not pairs:
        return '' if rng.random() < 0.5 else '?'
    parts = []
    for k, v in pairs:
        k_enc = _pct_encode(k, rng)
        v_enc = _pct_encode(v, rng)
        if k_enc and rng.random() < 0.15:
            # empty value form
            parts.append(k_enc)
        else:
            parts.append(f"{k_enc}={v_enc}")
    # allow a dangling & sometimes
    q = '&'.join(parts)
    if rng.random() < 0.1:
        q += '&'
    return '?' + q


def _rand_fragment(rng: random.Random) -> str:
    if rng.random() < 0.5:
        return ''
    length = rng.randint(0, 20)
    charset = SAFE_UNRESERVED + SUBDELIMS + "/?:@"
    frag = ''.join(rng.choice(charset) for _ in range(length))
    return '#' + frag


def _rand_authority(rng: random.Random) -> str:
    userinfo = _rand_userinfo(rng)
    host_choice = rng.random()
    if host_choice < 0.33:
        host = _rand_hostname(rng)
    elif host_choice < 0.66:
        host = _rand_ipv4(rng)
    else:
        host = '[' + _rand_ipv6(rng) + ']'
    port = '' if rng.random() < 0.5 else _rand_port(rng, for_tracker=False)
    return userinfo + host + port


def _rand_scheme(rng: random.Random, tracker_hint: bool) -> str:
    if tracker_hint:
        return rng.choice(['http', 'https'])
    return rng.choice(['http', 'https', 'udp', 'ws', 'wss'])


def _rand_path(tracker_hint: bool, rng: random.Random) -> str:
    # For tracker validation, include announce/scrape patterns often
    if tracker_hint and rng.random() < 0.8:
        base = rng.choice(['announce', 'scrape', 'tracker/announce'])
        extra = _rand_path_segments(rng, 0, 2)
        return '/' + base + ('' if not extra else '/' + '/'.join(extra))
    segments = _rand_path_segments(rng, 0, 6)
    path = '/' + '/'.join(segments) if segments else '/'
    return path


def _make_url(rng: random.Random, tracker_hint: bool) -> str:
    scheme = _rand_scheme(rng, tracker_hint)
    authority = _rand_authority(rng)
    path = _rand_path(tracker_hint, rng)
    query = _build_query(_rand_query_pairs(rng), rng)
    fragment = _rand_fragment(rng)
    url = f"{scheme}://{authority}{path}{query}{fragment}"
    # Keep within 1024 for FUZZ_PARAM_STR usage in stubs that trim; our contract limits to 4096
    if len(url) > 1024:
        url = url[:1024]
    return url


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Choose a scenario matching the fuzz stubs
    scenario = rng.choice([
        'generic',           # tr_urlIsValid, tr_urlParse
        'tracker',           # tr_urlIsValidTracker, tr_urlParseTracker, tr_urlTrackerLogName
        'blocklist',         # tr_blocklistSetURL expects an URL string
        'fetch_path',        # random suffix used as path in fetch stubs
    ])

    if scenario == 'fetch_path':
        # The stubs prepend http://example.com/ + path. Provide a path-ish segment
        segs = _rand_path_segments(rng, 1, 6)
        # sanitize spaces as the stub does; we avoid spaces to begin with
        path = '/'.join(segs)
        # Add query occasionally to see range/cookie handling alongside
        if rng.random() < 0.5:
            path += _build_query(_rand_query_pairs(rng), rng)
        data = path
    else:
        tracker_hint = (scenario == 'tracker')
        data = _make_url(rng, tracker_hint)

    # Final guardrails
    if not data:
        data = 'http://example.com/'
    data = data[:4096]
    return data.encode('utf-8')

import random
import struct
from typing import List, Tuple, Union

# This generator focuses on producing valid bencoded data, especially
# .torrent-like metainfo dictionaries and other valid bencode constructs
# that exercise both bencode and JSON parsers (for JSON runs it will still
# be fed; success optional). It keeps outputs <= 4096 bytes and varies by seed.

BValue = Union[int, bytes, list, dict]


def _rand_str_bytes(r: random.Random, min_len=0, max_len=64) -> bytes:
    n = r.randint(min_len, max_len)
    # Prefer URL/path/identifier friendly plus some unicode-ish bytes within latin-1
    alphabet = b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_.:/?&=%+[](){}@!#,$'\" "
    s = bytes(r.choice(alphabet) for _ in range(n))
    # Avoid leading/trailing spaces sometimes
    if n > 0 and r.random() < 0.5:
        s = s.strip() or b"x"
    return s


def _rand_int(r: random.Random, small_bias=True) -> int:
    if small_bias and r.random() < 0.75:
        # common small ints and sentinel-like values
        choices = [0, 1, -1, 2, 10, 99, 100, 256, 512, 1024, 65535, 2**31-1, 2**31, 2**32-1]
        return r.choice(choices)
    # broader range
    lo = -2**63 + 1
    hi = 2**63 - 1
    return r.randint(lo, hi)


def bencode(value: BValue) -> bytes:
    if isinstance(value, int):
        return b"i" + str(value).encode("ascii") + b"e"
    if isinstance(value, bytes):
        return str(len(value)).encode("ascii") + b":" + value
    if isinstance(value, str):
        b = value.encode("utf-8", errors="ignore")
        return str(len(b)).encode("ascii") + b":" + b
    if isinstance(value, list):
        return b"l" + b"".join(bencode(v) for v in value) + b"e"
    if isinstance(value, dict):
        # bencode dicts must be sorted by key (as raw bytes)
        items: List[Tuple[bytes, BValue]] = []
        for k, v in value.items():
            kb = k if isinstance(k, bytes) else str(k).encode("utf-8", errors="ignore")
            items.append((kb, v))
        items.sort(key=lambda kv: kv[0])
        out = bytearray()
        out += b"d"
        for kb, v in items:
            out += str(len(kb)).encode("ascii") + b":" + kb
            out += bencode(v)
        out += b"e"
        return bytes(out)
    raise TypeError("Unsupported type for bencode")


# Build pieces and info dicts akin to .torrent with varieties

def _rand_piece_length(r: random.Random) -> int:
    # Typical piece sizes: 16 KiB .. 4 MiB
    powers = [14, 15, 16, 17, 18, 19, 20, 21, 22]
    return 1 << r.choice(powers)


def _rand_pieces_blob(r: random.Random, n_pieces: int) -> bytes:
    # SHA1 digests are 20 bytes each; content can be random to remain valid shape
    return bytes(r.getrandbits(8) for _ in range(20 * max(1, n_pieces)))


def _build_single_file_info(r: random.Random) -> dict:
    length = r.randint(1, 50_000_000)
    piece_length = _rand_piece_length(r)
    n_pieces = max(1, (length + piece_length - 1) // piece_length)
    info = {
        b"name": _rand_str_bytes(r, 1, 32),
        b"piece length": piece_length,
        b"pieces": _rand_pieces_blob(r, n_pieces),
        b"length": length,
    }
    # Optional fields
    if r.random() < 0.3:
        info[b"private"] = 1
    if r.random() < 0.4:
        info[b"source"] = _rand_str_bytes(r, 3, 12)
    return info


def _build_multi_file_info(r: random.Random) -> dict:
    piece_length = _rand_piece_length(r)
    n_files = r.randint(2, 12)
    files = []
    total = 0
    for _ in range(n_files):
        length = r.randint(1, 10_000_000)
        total += length
        # path is a list of path components as strings
        depth = 1 + (0 if r.random() < 0.6 else r.randint(1, 3))
        comps = [(_rand_str_bytes(r, 1, 12)).decode('latin1', errors='ignore') or 'x' for _ in range(depth)]
        files.append({
            b"length": length,
            b"path": comps,
        })
    n_pieces = max(1, (total + piece_length - 1) // piece_length)
    info = {
        b"name": _rand_str_bytes(r, 1, 24),
        b"piece length": piece_length,
        b"pieces": _rand_pieces_blob(r, n_pieces),
        b"files": files,
    }
    if r.random() < 0.35:
        info[b"private"] = 1
    return info


def _build_announce_list(r: random.Random) -> list:
    # trackers as list-of-lists
    def one_url() -> str:
        scheme = r.choice(["http", "https", "udp"])
        host = ".".join(["t" + str(r.randint(0, 999)), "example", r.choice(["org", "com", "net"])])
        path = "/announce"
        if r.random() < 0.3:
            path += "?key=" + str(r.randint(0, 999999))
        return f"{scheme}://{host}{path}"
    tiers = r.randint(1, 4)
    ann = []
    for _ in range(tiers):
        tier_n = r.randint(1, 3)
        ann.append([one_url() for _ in range(tier_n)])
    return ann


def _build_torrent_metainfo(r: random.Random) -> dict:
    single = r.random() < 0.6
    info = _build_single_file_info(r) if single else _build_multi_file_info(r)
    meta = {
        b"info": info,
        b"created by": b"gen",
        b"creation date": int(r.randint(1_600_000_000, 1_800_000_000)),
    }
    # Add announce variants
    if r.random() < 0.7:
        meta[b"announce"] = r.choice(_build_announce_list(r)[0])
    if r.random() < 0.8:
        meta[b"announce-list"] = _build_announce_list(r)
    # Optional webseeds
    if r.random() < 0.4:
        meta[b"url-list"] = [f"https://cdn{r.randint(1,9)}.example.net/seed" for _ in range(r.randint(1, 3))]
    # Optional comment & encoding
    if r.random() < 0.5:
        meta[b"comment"] = _rand_str_bytes(r, 3, 60)
    if r.random() < 0.25:
        meta[b"encoding"] = r.choice([b"UTF-8", b"UTF8", b"utf-8"]) 
    return meta


def _build_simple_values(r: random.Random) -> BValue:
    # Produce non-metainfo valid bencoded values to vary parser coverage
    choice = r.random()
    if choice < 0.25:
        return _rand_int(r)
    if choice < 0.5:
        return _rand_str_bytes(r, 0, 64)
    if choice < 0.75:
        # list of mixed values
        return [
            _rand_int(r),
            _rand_str_bytes(r, 0, 32),
            [_rand_int(r) for _ in range(r.randint(0, 4))],
        ]
    # dict with sorted keys enforced in bencode()
    d = {}
    for _ in range(r.randint(1, 6)):
        d[_rand_str_bytes(r, 1, 10)] = r.choice([
            _rand_int(r),
            _rand_str_bytes(r, 0, 32),
            [_rand_int(r) for _ in range(r.randint(0, 3))],
        ])
    return d


def _maybe_wrap_for_inplace(r: random.Random, data: bytes) -> bytes:
    # The fuzzer sometimes enables inplace() which benefits from reasonably sized inputs
    if len(data) > 2048 and r.random() < 0.5:
        return data[:2048]
    return data


def generate(seed: int) -> bytes:
    r = random.Random(seed)

    # Choose between producing a torrent metainfo dict or other valid bencode value
    if r.random() < 0.7:
        val = _build_torrent_metainfo(r)
    else:
        val = _build_simple_values(r)

    out = bencode(val)

    # Ensure size limit and adapt to parse paths using inplace/compact
    out = _maybe_wrap_for_inplace(r, out)

    # Keep under global cap
    if len(out) > 4096:
        out = out[:4096]

    return out

import json
import random
import string
from typing import Any, Dict, List, Tuple

# This generator focuses on producing valid JSON inputs suitable for:
# - tr_variant_serde::parse / ::inplace / ::end (JSON or bencode). We only generate JSON here,
#   but keep sizes small and varied. JSON inputs remain valid and interesting.
# - tr_rpc_request_exec: expects a JSON-RPC 2.0 request object with fields jsonrpc, method, params, id.
#   We produce various valid requests with different methods and parameter shapes.
#
# Strategy
# - Randomly choose between emitting:
#   1) A JSON-RPC request object tailored for Transmission methods, with valid shapes and small payloads
#   2) A generic but richly-featured JSON value (objects/arrays/strings/numbers/bools/null)
# - Keep output size <= 2048 bytes (well under the 4096 limit and within fuzzer caps)
# - Ensure all outputs are valid JSON (no trailing commas, properly escaped strings).

METHODS = [
    "session-get", "session-stats", "torrent-get", "torrent-add",
    "torrent-set", "torrent-remove", "torrent-start", "torrent-stop",
    "port-test", "blocklist-update", "free-space"
]

# Small field sets for torrent-get to keep payloads minimal yet valid
TORRENT_GET_FIELDS_VARIANTS = [
    ["id", "name"],
    ["id", "hashString", "isPrivate"],
    ["id", "totalSize", "pieceCount"],
]

# Some plausible params for different methods
def make_params_for_method(rng: random.Random, method: str) -> Dict[str, Any]:
    if method == "torrent-get":
        fields = rng.choice(TORRENT_GET_FIELDS_VARIANTS)
        return {"fields": fields}
    if method == "free-space":
        # Use short paths to keep JSON small
        sample_dirs = ["/tmp", "/", ".", "/var", "/home/user", "C:/", "D:/Downloads"]
        return {"path": rng.choice(sample_dirs)}
    if method in ("torrent-start", "torrent-stop", "torrent-remove"):
        # Provide a small set of ids (integers or single id)
        ids: List[int] = sorted(set(rng.randrange(1, 10) for _ in range(rng.randint(1, 3))))
        return {"ids": ids}
    if method == "torrent-add":
        # Either magnet link or metainfo
        if rng.random() < 0.5:
            # Simple magnet with one tracker
            xt = "urn:btih:" + ''.join(rng.choice('0123456789ABCDEF') for _ in range(40))
            dn = "example" + str(rng.randrange(100))
            tr = "udp://tracker.example.org:80/announce"
            magnet = f"magnet:?xt={xt}&dn={dn}&tr={tr}"
            return {"filename": magnet, "paused": rng.choice([True, False])}
        else:
            # Minimal .torrent-like field via metainfo (base64-pretend short string)
            meta = "d5:filesld6:lengthi0e4:pathl8:emptyeee"  # bencode-ish text inside JSON
            return {"metainfo": meta, "paused": rng.choice([True, False])}
    if method == "torrent-set":
        # Toggle a few flags
        body: Dict[str, Any] = {}
        if rng.random() < 0.5:
            body["ids"] = [rng.randrange(1, 5)]
        if rng.random() < 0.5:
            body["uploadLimit"] = rng.randrange(10, 1000)
            body["uploadLimited"] = True
        if rng.random() < 0.5:
            body["downloadLimit"] = rng.randrange(10, 1000)
            body["downloadLimited"] = True
        if rng.random() < 0.5:
            body["seedRatioMode"] = rng.choice([0, 1, 2])
            body["seedRatioLimit"] = round(rng.uniform(0.1, 5.0), 2)
        return body if body else {"ids": [rng.randrange(1, 5)]}
    if method == "session-get":
        return {}  # No params required
    if method == "session-stats":
        return {"cumulative": rng.choice([True, False])}
    if method == "port-test":
        return {}
    if method == "blocklist-update":
        return {}
    # default
    return {}

# JSON-RPC id can be number or string; provide both variants
def make_id(rng: random.Random) -> Any:
    if rng.random() < 0.5:
        return rng.randrange(0, 1 << 30)
    # short random string id
    return ''.join(rng.choice(string.ascii_letters + string.digits) for _ in range(rng.randint(1, 12)))

# Build a valid JSON-RPC request
def build_jsonrpc_request(rng: random.Random) -> str:
    method = rng.choice(METHODS)
    req = {
        "jsonrpc": "2.0",
        "method": method,
        "params": make_params_for_method(rng, method),
        "id": make_id(rng),
    }
    return json.dumps(req, separators=(",", ":"))

# Generic JSON value builders to exercise serde.parse paths
PRIMITIVE_VALUES = [
    lambda rng: None,
    lambda rng: True,
    lambda rng: False,
    lambda rng: rng.uniform(-1e6, 1e6),
    lambda rng: rng.randrange(-1_000_000, 1_000_000),
    lambda rng: ''.join(rng.choice(string.ascii_letters + string.digits + " _-:/?@.#$") for _ in range(rng.randint(0, 24))),
]

def build_array(rng: random.Random, depth: int) -> List[Any]:
    length = rng.randint(0, 6)
    arr: List[Any] = []
    for _ in range(length):
        arr.append(build_value(rng, depth + 1))
    return arr

def build_object(rng: random.Random, depth: int) -> Dict[str, Any]:
    n = rng.randint(0, 6)
    obj: Dict[str, Any] = {}
    for _ in range(n):
        key = ''.join(rng.choice(string.ascii_letters + string.digits + "_-:") for _ in range(rng.randint(1, 12)))
        obj[key] = build_value(rng, depth + 1)
    return obj

def build_value(rng: random.Random, depth: int = 0) -> Any:
    # Limit nesting depth to keep size reasonable and avoid excessive recursion
    if depth > 3:
        return rng.choice(PRIMITIVE_VALUES)(rng)
    choice = rng.random()
    if choice < 0.35:
        return build_object(rng, depth)
    if choice < 0.7:
        return build_array(rng, depth)
    return rng.choice(PRIMITIVE_VALUES)(rng)

def build_generic_json(rng: random.Random) -> str:
    value = build_value(rng, 0)
    return json.dumps(value, separators=(",", ":"))

# Top-level generator
def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Choose between JSON-RPC request and generic JSON
    # Bias slightly towards JSON-RPC to exercise tr_rpc_request_exec
    if rng.random() < 0.6:
        out = build_jsonrpc_request(rng)
    else:
        out = build_generic_json(rng)

    # Ensure size limits for fuzz stubs; truncate safely at a boundary
    # We prefer not to truncate in the middle of multi-byte since JSON is ASCII here.
    max_len = 2048
    if len(out) > max_len:
        # If too long, rebuild simpler rather than truncating into invalid JSON
        out = build_generic_json(rng)
        if len(out) > max_len:
            out = out[:max_len]
            # As a fallback, if we had to slice, try to make it valid by wrapping as a JSON string
            # This ensures valid JSON even if slice broke structure
            out = json.dumps(out)
            if len(out) > max_len:
                out = out[:max_len]
    return out.encode("utf-8")
